        persistLaboratoryUnit({ account, order, index, action: "unsigned_certificate_generated", nextUnit: { ...unit, labWork: { ...unit.labWork, status: status2, documents: [...unit.labWork.documents, version], certificateWorkflow: { ...unit.labWork.certificateWorkflow, unsignedVersions: [...unit.labWork.certificateWorkflow.unsignedVersions, version] } } } });
